import cp from "node:child_process";
function main(): void {
  const r = cp.spawnSync("sh", ["-c", "exit 3"]);
  console.log(Object.keys(r), r.status, r.signal);
  const r2 = cp.spawnSync("nonexistent-cmd-xyz") as any;
  console.log(Object.keys(r2), r2.status, r2.error.code, r2.error.errno, r2.error.syscall, r2.error.path, r2.error.spawnargs, r2.error.message, Object.keys(r2.error));
  try { cp.execSync("exit 2", { stdio: "pipe" }); } catch (e: any) { console.log(e.status, e.message, Object.keys(e)); }
  try { cp.execSync("echo bad >&2; exit 2", { stdio: "pipe" }); } catch (e: any) { console.log(e.message); }
}
